import test from 'node:test';
import assert from 'node:assert/strict';
import { truncate } from '../src/text.js';

test('truncated result is never longer than max', () => {
  const text = 'the quick brown fox jumps over the lazy dog';
  for (const max of [0, 1, 2, 3, 4, 5, 10, 20]) {
    const result = truncate(text, max);
    assert.ok(result.length <= max, `expected length <= ${max}, got ${result.length}`);
  }
});

test('truncated result ends in ... when it had to cut', () => {
  const text = 'the quick brown fox jumps over the lazy dog';
  assert.equal(truncate(text, 10), 'the quick...');
  assert.equal(truncate(text, 4), 't...');
});

test('short text is left alone', () => {
  assert.equal(truncate('hi', 5), 'hi');
  assert.equal(truncate('hello', 5), 'hello');
});

